СсылкаДанных = Справочники.кфк_т_ТестовыйСправочник.ПолучитьСсылку(Новый УникальныйИдентификатор("a6cb2c9f-1564-4173-b24d-7a65c9aa79e9"));
Данные = Справочники.кфк_т_ТестовыйСправочник.СоздатьЭлемент();
Данные.УстановитьСсылкуНового(СсылкаДанных);
Данные.Наименование = "VA-a6cb2c9f-1564-4173-b24d-7a65c9aa79e9";
Данные.Число = 17;
Данные.Булево = Истина;
Данные.ДатаИВремя = Дата(2026, 1, 1, 10, 0, 0);
Данные.Комментарий = "VA: собственные данные";
Данные.Перечисление = Перечисления.кфк_т_ТестовоеПеречисление[0];
СтрокаТЧ = Данные.ТабличнаяЧасть.Добавить();
СтрокаТЧ.ДатаИВремя = Дата(2026, 1, 1, 10, 0, 1);
СтрокаТЧ.Строка = "VA-a6cb2c9f-1564-4173-b24d-7a65c9aa79e9-строка";
кфкИнтеграция.Отключить(Данные);
Данные.ОбменДанными.Загрузка = Истина;
Данные.Записать();
Ключи = кфкОбработкаСобытийСлужебный.КлючЗаписиИсходящихСообщений(Данные.Ссылка);
Если Ключи = Неопределено Или Ключи.Количество() = 0 Тогда
ВызватьИсключение "Не найдены настройки обмена тестового справочника.";
КонецЕсли;
Объект.ЗначениеНаСервере = Ключи[0] + "|" + ПолучитьНавигационнуюСсылку(Данные.Ссылка);

Настройка = кфк_т_ТестовыеДанные.СсылкаПродюсераОбщий();
Для НомерЗаписи = 1 По 3 Цикл
Запись = РегистрыСведений.кфкИсходящиеСообщения.СоздатьМенеджерЗаписи();
Запись.КлючЗаписи = ?(НомерЗаписи = 3, "VA-a6cb2c9f-1564-4173-b24d-7a65c9aa79e9-3", "B99DFA6C0956C19EF21D00FA4A4E8ED2FE3CBC62CF1BDF413988DB63CAE7C806");
Запись.МеткаРегистрации = Число(?(НомерЗаписи = 2, "28571877518000000000500000014", "28571877517000000000500000013"));
Запись.МеткаИзменения = Запись.МеткаРегистрации;
Запись.Статус = Перечисления.кфкСтатусыСообщений.Выгружено;
Запись.Продюсер = Настройка;
Запись.КлючСообщения = "VA-a6cb2c9f-1564-4173-b24d-7a65c9aa79e9-" + Формат(НомерЗаписи, "ЧГ=0");
Запись.КоличествоОбработок = 3;
Запись.ДатаОбработки = Дата(2026, 1, 1, 10, 0, 2);
Запись.ДлОбработкиМС = 125;
Запись.ТипОбъект = "Справочник.кфк_т_ТестовыйСправочник";
Запись.ТипИсходныхДанных = "Структура";
Запись.КлючОбъекта = "a6cb2c9f-1564-4173-b24d-7a65c9aa79e9";
Запись.ДатаРегистрации = Дата(2026, 1, 1, 10, 0, НомерЗаписи);
Запись.КоличествоВыгрузок = 2;
Запись.ДатаВыгрузки = Дата(2026, 1, 1, 10, 0, 3);
Запись.ИсходныеДанные = кфкОбщегоНазначенияСлужебный.ЗначениеВХранилище(
Новый Структура("Маркер", Запись.КлючСообщения));
Заголовки = Новый Соответствие;
Заголовки.Вставить("va-marker", Запись.КлючСообщения);
Запись.Заголовки = кфкОбщегоНазначенияСлужебный.ЗначениеВХранилище(Заголовки);
Запись.ТелоСообщения = кфкОбщегоНазначенияСлужебный.ЗначениеВХранилище(
"{""marker"":""" + Запись.КлючСообщения + """}");
Запись.ТекстЖурнала = "VA: исходный журнал";
Запись.Записать();
КонецЦикла;

Идентификатор = Новый УникальныйИдентификатор("a6cb2c9f-1564-4173-b24d-7a65c9aa79e9");
БазовыйКлюч = "VA-" + Строка(Идентификатор);
Ключ = "B99DFA6C0956C19EF21D00FA4A4E8ED2FE3CBC62CF1BDF413988DB63CAE7C806";
Если "кфкИсходящиеСообщения" = "кфкИсходящиеСообщения" Тогда
Менеджер = РегистрыСведений.кфкИсходящиеСообщения;
Если Ключ <> БазовыйКлюч Тогда
Ссылка = Справочники.кфк_т_ТестовыйСправочник.ПолучитьСсылку(Идентификатор);
КлючиОбъекта = кфкОбработкаСобытийСлужебный.КлючЗаписиИсходящихСообщений(Ссылка);
Если КлючиОбъекта = Неопределено Или КлючиОбъекта.Найти(Ключ) = Неопределено Тогда
ВызватьИсключение "Ключ исходящих сообщений не принадлежит тестовому объекту.";
КонецЕсли;
КонецЕсли;
ИначеЕсли "кфкИсходящиеСообщения" = "кфкВходящиеСообщения" Тогда
Менеджер = РегистрыСведений.кфкВходящиеСообщения;
Если Ключ <> БазовыйКлюч Тогда
ВызватьИсключение "Ключ входящих сообщений не принадлежит тестовому объекту.";
КонецЕсли;
Иначе
ВызватьИсключение "Неизвестный регистр сообщений.";
КонецЕсли;
Для Каждого ТекущийКлюч Из СтрРазделить(Ключ + "," + БазовыйКлюч + "-3", ",") Цикл
Сообщения = кфкОбщегоНазначенияСлужебный.СоздатьНаборЗаписей(Менеджер);
Сообщения.Отбор.КлючЗаписи.Установить(ТекущийКлюч);
Сообщения.Записать();
Очередь = кфкОбщегоНазначенияСлужебный.СоздатьНаборЗаписей(РегистрыСведений.кфкОчередьПотоков);
Очередь.Отбор.Ключ.Установить(ТекущийКлюч);
Очередь.Записать();
КонецЦикла;

Идентификатор = Новый УникальныйИдентификатор("a6cb2c9f-1564-4173-b24d-7a65c9aa79e9");
Ссылка = Справочники.кфк_т_ТестовыйСправочник.ПолучитьСсылку(Идентификатор);
Если ОбщегоНазначения.СсылкаСуществует(Ссылка) Тогда
Данные = Ссылка.ПолучитьОбъект();
Если Данные.Наименование <> "VA-" + Строка(Идентификатор) Тогда
ВызватьИсключение "Имя тестового объекта сообщений изменилось; очистка остановлена.";
КонецЕсли;
кфкИнтеграция.Отключить(Данные);
Данные.ОбменДанными.Загрузка = Истина;
Данные.Удалить();
КонецЕсли;
